    const ev=document.getElementById('talentEvidenceV140');const radar=document.createElement('div');radar.id='talentOpportunityRadarV140';radar.className='mt-5 rounded-3xl border border-violet-100 bg-violet-50/50 p-5 sm:p-6';radar.innerHTML='<p class="text-sm text-slate-500">Analizando oportunidades...</p>';ev?.insertAdjacentElement('afterend',radar);
