function renderTalentApprovalState(){
  const p=talentData?.profile||{},d=v140State.intelligence||{},status=p.auto_validation_status||d.status||'building',cfg=v140StatusCfg(status);
  const title=document.getElementById('talentApprovalTitle'),text=document.getElementById('talentApprovalText'),badge=document.getElementById('talentApprovalBadge'),btn=document.getElementById('talentSubmitReviewBtn'),reason=document.getElementById('talentApprovalReason'),visible=document.getElementById('talentVisible'),label=document.getElementById('talentVisibleLabel');
  if(!title||!text||!badge)return;title.textContent=cfg.title;text.textContent=cfg.text;badge.textContent=cfg.label;badge.className=`px-3 py-1.5 rounded-full text-[10px] font-extrabold ${cfg.cls}`;
  if(btn){btn.classList.remove('hidden');btn.onclick=()=>refreshMyProfileV140(true);btn.innerHTML='<i class="fa-solid fa-rotate mr-2"></i>Optimizar perfil';}
  const missing=d.missing||[],exceptions=d.exceptions||[],actions=d.next_actions||[];
  if(reason){reason.classList.remove('hidden');reason.className='mt-4 rounded-2xl bg-white/80 border border-blue-100 p-4';reason.innerHTML=`<div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3"><div><p class="text-[10px] uppercase tracking-widest font-black text-blue-600">Cobertura del perfil</p><div class="mt-1 flex items-end gap-2"><span class="text-3xl font-black text-lutmin-dark">${Number(d.score??p.auto_validation_score??0)}%</span><span class="pb-1 text-xs text-slate-500">datos estructurados</span></div></div><div class="flex-1 max-w-md h-2 rounded-full bg-slate-100 overflow-hidden"><div class="h-full bg-lutmin-light rounded-full" style="width:${Math.max(0,Math.min(100,Number(d.score??0)))}%"></div></div></div>${exceptions.length?`<div class="mt-4 rounded-xl bg-amber-50 p-3"><p class="text-[10px] font-black text-amber-700">REQUIERE REVISIÓN HUMANA POR EXCEPCIÓN</p><div class="mt-2 space-y-1">${exceptions.map(x=>`<p class="text-xs text-amber-800">• ${v140Esc(x.label)}</p>`).join('')}</div></div>`:''}${status==='building'&&missing.length?`<div class="mt-4"><p class="text-[10px] uppercase font-black text-slate-400">Qué falta para habilitarlo automáticamente</p><div class="mt-2 flex flex-wrap gap-2">${missing.slice(0,6).map(x=>`<button onclick="goToProfileActionV140('${v140Esc(x.code)}')" class="px-3 py-1.5 rounded-xl bg-slate-50 text-slate-700 text-[10px] font-bold">${v140Esc(x.label)}</button>`).join('')}</div></div>`:''}${actions.length?`<div class="mt-4"><p class="text-[10px] uppercase font-black text-slate-400">Siguiente mejor acción</p><p class="mt-1 text-sm font-extrabold text-lutmin-dark">${v140Esc(actions[0]?.label||'')}</p></div>`:''}`;}
  if(visible){visible.disabled=status!=='active';visible.classList.toggle('opacity-50',status!=='active');}
  if(label)label.textContent=status==='active'?'Mostrarme a empresas':'Se habilitará cuando el perfil esté activo';
}

function goToProfileActionV140(code){
  const map={headline:'talentHeadline',location:'talentCity',contact:'talentPhone',bio:'talentBio',goal:'talentDesiredRole',skills:'talentSkillName',experience:'talentExpCompany',cv:'talentCvAgentV140',education:'talentEducationV140'};const el=document.getElementById(map[code]||'talentProfileForm');el?.scrollIntoView({behavior:'smooth',block:'center'});if(el?.focus)el.focus();
}

async function loadV140ProfileData(){
  if(!supabaseClient||currentLutminUser?.role!=='student')return;ensureV140StudentUI();
  const [i,e,edu]=await Promise.all([supabaseClient.rpc('my_profile_intelligence_v140'),supabaseClient.rpc('my_evidence_map_v140'),supabaseClient.from('talent_education_v140').select('*').eq('user_id',currentLutminUser.id).order('start_date',{ascending:false})]);
  if(!i.error)v140State.intelligence=i.data||{};if(!e.error)v140State.evidence=e.data||{};if(!edu.error)v140State.education=edu.data||[];
  renderTalentApprovalState();renderEvidenceMapV140();renderEducationV140();renderOpportunityRadarV140();
}

async function refreshMyProfileV140(notify=false){
  if(!supabaseClient||currentLutminUser?.role!=='student')return null;const {data,error}=await supabaseClient.rpc('refresh_my_profile_intelligence_v140');if(error){console.error(error);if(notify)showToast('No pude actualizar el análisis del perfil.');return null;}v140State.intelligence=data||{};if(talentData?.profile){talentData.profile.auto_validation_status=data?.status;talentData.profile.auto_validation_score=data?.score;talentData.profile.approval_status=data?.status==='active'?'approved':data?.status==='review_required'?'pending':'draft';}
  renderTalentApprovalState();if(notify)showToast(data?.status==='active'?'Perfil habilitado automáticamente.':data?.status==='review_required'?'El perfil requiere revisión humana por una inconsistencia puntual.':'Perfil actualizado. Te mostramos qué falta para habilitarlo.');return data;
}

function evidenceStateV140(s){const valid=s.validation&&s.validation.status==='valid',course=(s.course_evidence||[]).length,cv=(s.cv_evidence||[]).length,inter=(s.interview_evidence||[]).length;if(valid)return['Validada','bg-emerald-50 text-emerald-700'];if(course)return['Respaldada por formación','bg-blue-50 text-blue-700'];if(cv||inter)return['Con evidencia declarada','bg-violet-50 text-violet-700'];return['Declarada','bg-slate-100 text-slate-600'];}
function renderEvidenceMapV140(){const root=document.getElementById('talentEvidenceV140');if(!root)return;const d=v140State.evidence||{},skills=d.skills||[],imports=d.cv_imports||[];root.innerHTML=`<div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-4"><div><p class="text-[10px] uppercase tracking-widest font-black text-violet-600">Motor de Evidencias</p><h3 class="mt-1 text-xl font-black text-lutmin-dark">No todas las competencias significan lo mismo.</h3><p class="mt-2 text-xs text-slate-500 max-w-3xl">Lutmin separa lo que declaraste, lo detectado en CV/entrevista, lo adquirido por formación y lo validado mediante evaluación. Una mención en CV nunca se convierte sola en “validada”.</p></div><div class="text-right"><p class="text-[10px] uppercase font-bold text-slate-400">CV analizados</p><p class="text-2xl font-black text-lutmin-dark">${imports.length}</p></div></div><div class="mt-5 grid md:grid-cols-2 gap-3">${skills.length?skills.map(s=>{const st=evidenceStateV140(s);return `<div class="rounded-2xl border border-slate-100 p-4"><div class="flex items-start justify-between gap-3"><div><p class="font-extrabold text-sm text-lutmin-dark">${v140Esc(s.skill)}</p><p class="mt-1 text-[10px] text-slate-400">Nivel declarado ${Number(s.level||0)}/5</p></div><span class="px-2.5 py-1 rounded-full text-[9px] font-black ${st[1]}">${st[0]}</span></div><div class="mt-3 flex flex-wrap gap-1.5"><span class="px-2 py-1 rounded-lg bg-slate-100 text-slate-600 text-[9px] font-bold">DECLARADA</span>${(s.cv_evidence||[]).length?`<span class="px-2 py-1 rounded-lg bg-violet-50 text-violet-700 text-[9px] font-bold">CV ${(s.cv_evidence||[]).length}</span>`:''}${(s.interview_evidence||[]).length?`<span class="px-2 py-1 rounded-lg bg-cyan-50 text-cyan-700 text-[9px] font-bold">ENTREVISTA ${(s.interview_evidence||[]).length}</span>`:''}${(s.course_evidence||[]).length?`<span class="px-2 py-1 rounded-lg bg-blue-50 text-blue-700 text-[9px] font-bold">CURSO ${(s.course_evidence||[]).length}</span>`:''}${s.validation?`<span class="px-2 py-1 rounded-lg ${s.validation.status==='valid'?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700'} text-[9px] font-bold">${s.validation.status==='valid'?'VALIDADA':'VALIDACIÓN '+String(s.validation.status||'').toUpperCase()}</span>`:''}</div></div>`}).join(''):'<div class="md:col-span-2 rounded-2xl bg-slate-50 p-5 text-sm text-slate-500">Todavía no hay competencias. Podés cargarlas manualmente o dejar que el Agente de CV te proponga algunas.</div>'}</div>`;}

async function saveEducationV140(e){e.preventDefault();const f=e.target,current=f.current.checked;const payload={user_id:currentLutminUser.id,institution:f.institution.value.trim(),title:f.title.value.trim(),level:f.level.value||null,start_date:f.start.value||null,end_date:current?null:(f.end.value||null),current,source_type:'manual'};const {error}=await supabaseClient.from('talent_education_v140').insert(payload);if(error)return showToast(error.message||'No pude guardar la formación.');f.reset();showToast('Formación agregada.');await loadV140ProfileData();}
async function deleteEducationV140(id){const {error}=await supabaseClient.from('talent_education_v140').delete().eq('id',id).eq('user_id',currentLutminUser.id);if(error)return showToast('No pude eliminar la formación.');await loadV140ProfileData();}
function renderEducationV140(){const rows=v140State.education||[];const count=document.getElementById('talentEducationCountV140'),root=document.getElementById('talentEducationListV140');if(count)count.textContent=String(rows.length);if(!root)return;root.innerHTML=rows.length?rows.map(x=>`<div class="rounded-2xl bg-slate-50 p-4 flex justify-between gap-3"><div><p class="font-extrabold text-sm text-lutmin-dark">${v140Esc(x.title)}</p><p class="mt-1 text-xs text-slate-500">${v140Esc(x.institution)}${x.level?' · '+v140Esc(x.level):''}</p><p class="mt-1 text-[10px] text-slate-400">${x.start_date||'—'} → ${x.current?'Actualidad':x.end_date||'—'} · ${x.source_type==='cv'?'Detectado y confirmado desde CV':'Carga manual'}</p></div><button onclick="deleteEducationV140('${x.id}')" class="text-red-400 text-xs"><i class="fa-solid fa-trash"></i></button></div>`).join(''):'<p class="text-xs text-slate-400">Todavía no cargaste formación externa.</p>';}

function renderOpportunityRadarV140(){const root=document.getElementById('talentOpportunityRadarV140');if(!root||typeof buildAgentAnalysisV100!=='function')return;const jobs=(talentData?.jobs||[]).filter(j=>j.status==='published'||!j.status).map(j=>({job:j,a:buildAgentAnalysisV100(j)})).filter(x=>Number(x.a?.score||0)>0).sort((a,b)=>Number(b.a.score)-Number(a.a.score)).slice(0,4);root.innerHTML=`<div class="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3"><div><p class="text-[10px] uppercase tracking-widest font-black text-violet-600">Radar personal · motor local</p><h3 class="mt-1 text-xl font-black text-lutmin-dark">Oportunidades donde ya tenés evidencia relacionada.</h3><p class="mt-1 text-xs text-slate-500">No predice contrataciones. Ordena para vos las búsquedas según coincidencias documentales de tu propio perfil.</p></div><span class="px-3 py-1.5 rounded-full bg-emerald-50 text-emerald-700 text-[10px] font-black">API $0</span></div><div class="mt-4 grid md:grid-cols-2 gap-3">${jobs.length?jobs.map(x=>`<div class="rounded-2xl bg-white border border-violet-100 p-4"><div class="flex justify-between gap-3"><div><p class="text-[10px] uppercase font-bold text-slate-400">${v140Esc(x.job.company_name||'Lutmin')}</p><p class="mt-1 font-extrabold text-lutmin-dark">${v140Esc(x.job.title)}</p></div><span class="text-xl font-black text-violet-600">${Math.round(Number(x.a.score||0))}%</span></div><p class="mt-2 text-[10px] text-slate-500">Afinidad documental orientativa · ${v140Esc((x.a.matched||[]).slice(0,4).join(' · ')||'sin coincidencias textuales fuertes')}</p><button onclick="openSmartApplyV100('${x.job.id}')" class="mt-3 px-3 py-2 rounded-xl bg-lutmin-dark text-white text-[10px] font-bold">Preparar postulación</button></div>`).join(''):'<div class="md:col-span-2 text-sm text-slate-500">No hay búsquedas publicadas con coincidencias suficientes todavía.</div>'}</div>`;}

// ---------------- CV LOCAL ----------------
async function loadScriptV140(id,src){if(window[id])return true;const found=document.querySelector(`script[data-v140-lib="${id}"]`);if(found)return new Promise((res,rej)=>{if(window[id])return res(true);found.addEventListener('load',()=>res(true),{once:true});found.addEventListener('error',rej,{once:true});});return new Promise((res,rej)=>{const s=document.createElement('script');s.src=src;s.async=true;s.dataset.v140Lib=id;s.onload=()=>res(true);s.onerror=()=>rej(new Error('No pude cargar '+id));document.head.appendChild(s);});}
async function ensurePdfV140(){if(window.pdfjsLib)return true;await loadScriptV140('pdfjsLib','https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';return true;}
async function ensureMammothV140(){if(window.mammoth)return true;await loadScriptV140('mammoth','https://cdn.jsdelivr.net/npm/mammoth@1.8.0/mammoth.browser.min.js');return true;}
async function ensureTesseractV140(){if(window.Tesseract)return true;await loadScriptV140('Tesseract','https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js');return true;}
async function hashFileV140(file){try{const b=await file.arrayBuffer(),h=await crypto.subtle.digest('SHA-256',b);return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('');}catch(_){return '';}}
async function pdfTextV140(file){await ensurePdfV140();const ab=await file.arrayBuffer(),pdf=await pdfjsLib.getDocument({data:ab}).promise;let text='';for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i),c=await pg.getTextContent();text+='\n'+c.items.map(x=>x.str).join(' ');}return{text,pages:pdf.numPages};}
async function ocrImageV140(source,status){await ensureTesseractV140();const result=await Tesseract.recognize(source,'spa+eng',{logger:m=>{if(status&&m.status==='recognizing text')status.textContent=`OCR local: ${Math.round((m.progress||0)*100)}%`;}});return result?.data?.text||'';}
async function ocrPdfV140(file,status){await ensurePdfV140();await ensureTesseractV140();const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let out='';const max=Math.min(pdf.numPages,8);for(let i=1;i<=max;i++){if(status)status.textContent=`OCR local · página ${i}/${max}...`;const pg=await pdf.getPage(i),vp=pg.getViewport({scale:1.45}),canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=vp.width;canvas.height=vp.height;await pg.render({canvasContext:ctx,viewport:vp}).promise;out+='\n'+await ocrImageV140(canvas,status);}return out;}
async function readCvV140(file,status){const name=file.name.toLowerCase();if(name.endsWith('.txt')||file.type==='text/plain')return{ text:await file.text(),method:'txt'};if(name.endsWith('.docx')){await ensureMammothV140();const r=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return{text:r.value||'',method:'docx'};}if(name.endsWith('.pdf')||file.type==='application/pdf'){const r=await pdfTextV140(file);if((r.text||'').replace(/\s/g,'').length<120){if(status)status.textContent='El PDF parece escaneado. Iniciando OCR local (puede tardar)...';return{text:await ocrPdfV140(file,status),method:'pdf-ocr'};}return{text:r.text,method:'pdf-text'};}if(file.type.startsWith('image/')||/\.(png|jpe?g)$/i.test(name)){if(status)status.textContent='Imagen detectada. Iniciando OCR local...';return{text:await ocrImageV140(file,status),method:'image-ocr'};}throw new Error('Formato no compatible. Usá PDF, DOCX, TXT, JPG o PNG.');}

const v140SectionWords=['experiencia','experiencia laboral','experiencia profesional','trayectoria','formacion','formación','educacion','educación','estudios','competencias','habilidades','skills','cursos','certificaciones','idiomas','perfil','resumen','sobre mi','sobre mí','objetivo'];
function v140IsSection(line){const n=v140Norm(line);return v140SectionWords.some(x=>n===v140Norm(x)||n.startsWith(v140Norm(x)+' '))&&line.length<55;}
function v140DateRange(line){const n=v140Norm(line);let m=n.match(/(?:^|\s)(20\d{2}|19\d{2})\s*(?:-|–|—|a|hasta)\s*(actualidad|actual|presente|20\d{2}|19\d{2})(?:$|\s)/);if(m)return{start:`${m[1]}-01-01`,end:/actual|presente/.test(m[2])?null:`${m[2]}-12-31`,current:/actual|presente/.test(m[2])};m=n.match(/(\d{1,2})[/.\-](20\d{2}|19\d{2})\s*(?:-|–|—|a|hasta)\s*(?:(\d{1,2})[/.\-](20\d{2}|19\d{2})|(actualidad|actual|presente))/);if(m)return{start:`${m[2]}-${String(m[1]).padStart(2,'0')}-01`,end:m[5]?null:`${m[4]}-${String(m[3]).padStart(2,'0')}-28`,current:!!m[5]};return null;}
function splitRoleCompanyV140(line,prev){const seps=[' · ',' | ',' @ ',' en ',' - ',' – ',' — '];for(const s of seps){if(line.includes(s)){const a=line.split(s).map(x=>x.trim()).filter(Boolean);if(a.length>=2)return{position:a[0],company:a.slice(1).join(' ')};}}return{position:line||'Puesto a revisar',company:prev&&!v140IsSection(prev)?prev:'Empresa a revisar'};}
function sectionSliceV140(lines,startRe,endRe){const start=lines.findIndex(x=>startRe.test(v140Norm(x)));if(start<0)return lines;let end=lines.length;for(let i=start+1;i<lines.length;i++){if(endRe.test(v140Norm(lines[i]))&&v140IsSection(lines[i])){end=i;break;}}return lines.slice(start+1,end);}
function extractExperiencesV140(lines){const sec=sectionSliceV140(lines,/^(experiencia|trayectoria)/,/^(educacion|formacion|estudios|competencias|habilidades|skills|cursos|certificaciones|idiomas)/),out=[];for(let i=0;i<sec.length;i++){const dr=v140DateRange(sec[i]);if(!dr)continue;const l1=sec[i-1]||'',l2=sec[i-2]||'',rc=splitRoleCompanyV140(l1,l2);let desc=[];for(let j=i+1;j<Math.min(sec.length,i+5);j++){if(v140DateRange(sec[j])||v140IsSection(sec[j]))break;if(sec[j].length>15)desc.push(sec[j]);}if(rc.position&&rc.company)out.push({...rc,...dr,description:desc.join(' ').slice(0,900),confidence:rc.company==='Empresa a revisar'?.55:.78});}const seen=new Set();return out.filter(x=>{const k=v140Norm(`${x.company}|${x.position}|${x.start}`);if(seen.has(k))return false;seen.add(k);return true;}).slice(0,12);}
function extractEducationV140(lines){const sec=sectionSliceV140(lines,/^(educacion|formacion|estudios)/,/^(experiencia|competencias|habilidades|skills|idiomas|cursos|certificaciones)/),out=[];for(let i=0;i<sec.length;i++){const dr=v140DateRange(sec[i]);if(dr){const title=sec[i-1]||'',inst=sec[i-2]||'';if(title&&!v140IsSection(title))out.push({institution:inst&&!v140IsSection(inst)?inst:'Institución a revisar',title,...dr,level:'',confidence:.7});}else if(/universidad|instituto|facultad|escuela|tecnic|licenc|ingenier|bachiller|secundar|posgrado/i.test(v140Norm(sec[i]))){const next=sec[i+1]||'';if(next&&!v140DateRange(next)&&!v140IsSection(next))out.push({institution:sec[i],title:next,start:null,end:null,current:false,level:'',confidence:.55});}}const seen=new Set();return out.filter(x=>{const k=v140Norm(`${x.institution}|${x.title}`);if(seen.has(k))return false;seen.add(k);return true;}).slice(0,10);}
function skillCatalogV140(){const base=(competencyDataV33||[]).map(c=>({label:c.name,competency_id:c.competency_id||c.id||null,keywords:[c.name,c.code].filter(Boolean)}));const extras=[['Mantenimiento','mantenimiento preventivo','mantenimiento correctivo'],['Electricidad','electricidad','electrico','eléctrico','tableros eléctricos'],['Refrigeración','refrigeracion','refrigeración','aire acondicionado','climatizacion','climatización'],['Liderazgo','liderazgo','lider de equipo','líder de equipo'],['Coordinación de equipos','coordinacion','coordinación','manejo de personal','supervision','supervisión'],['Microsoft Excel','excel','planillas de calculo','planillas de cálculo'],['Atención al cliente','atencion al cliente','atención al cliente'],['Ventas','ventas','comercial'],['Recursos Humanos','recursos humanos','rrhh','capital humano'],['Selección de personal','seleccion de personal','selección de personal','reclutamiento'],['Gestión de calidad','iso 9001','gestion de calidad','gestión de calidad'],['Seguridad laboral','seguridad laboral','higiene y seguridad'],['Logística','logistica','logística'],['Inventario','inventario','pañol','panol'],['Plomería / Fontanería','plomeria','plomería','fontaneria','fontanería'],['Construcción en seco','durlock','construccion en seco','construcción en seco']];for(const x of extras){if(!base.some(b=>v140Norm(b.label)===v140Norm(x[0])))base.push({label:x[0],competency_id:null,keywords:x.slice(1)});}return base;}
function findExcerptV140(text,terms){const clean=String(text||'').replace(/\s+/g,' ').trim(),n=v140Norm(clean);for(const t of terms){const pos=n.indexOf(v140Norm(t));if(pos>=0){const start=Math.max(0,pos-100),end=Math.min(clean.length,pos+220);return clean.slice(start,end).trim();}}return clean.slice(0,280);}
function extractSkillsV140(text){const n=v140Norm(text),out=[];for(const c of skillCatalogV140()){const kws=(c.keywords||[]).filter(k=>String(k||'').length>=3),hits=kws.filter(k=>n.includes(v140Norm(k)));if(hits.length)out.push({skill:c.label,competency_id:c.competency_id||null,confidence:Math.min(.95,.62+hits.length*.1),excerpt:findExcerptV140(text,hits)});}return out.slice(0,20);}
function detectLocationV140(lines){const provinces=['Buenos Aires','CABA','Ciudad Autónoma de Buenos Aires','Córdoba','Chaco','Corrientes','Santa Fe','Mendoza','Tucumán','Neuquén','Entre Ríos','Misiones','Salta','Jujuy','Río Negro','Chubut','San Juan','San Luis','La Pampa','Formosa','Santiago del Estero','Catamarca','La Rioja','Santa Cruz','Tierra del Fuego'];for(const l of lines.slice(0,35)){const p=provinces.find(x=>v140Norm(l).includes(v140Norm(x)));if(p){const parts=l.split(/[,|·]/).map(x=>x.trim()).filter(Boolean);return{city:parts.length>1?parts[0]:(p==='Buenos Aires'?'Buenos Aires':''),province:p};}}return{city:'',province:''};}
function detectBioV140(lines){const i=lines.findIndex(x=>/^(perfil|resumen|sobre mi|sobre mí|objetivo profesional)/.test(v140Norm(x)));if(i<0)return'';const a=[];for(let j=i+1;j<Math.min(lines.length,i+6);j++){if(v140IsSection(lines[j]))break;a.push(lines[j]);}return a.join(' ').slice(0,1200);}
function detectHeadlineV140(lines){const me=v140Norm(currentLutminUser?.fullName||'');return lines.slice(0,14).find(x=>{const n=v140Norm(x);return x.length>=4&&x.length<=95&&!v140IsSection(x)&&!n.includes('@')&&!/https?:|linkedin|\+?\d{6,}/i.test(x)&&n!==me&&!/curriculum|currículum|cv\b/i.test(n);})||'';}
function analyzeCvTextV140(text,file,method){const lines=String(text||'').split(/\r?\n| {3,}/).map(x=>x.trim()).filter(Boolean),flat=lines.join('\n');const email=(flat.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]||'';const linkedin=(flat.match(/https?:\/\/(?:www\.)?linkedin\.com\/[^\s)]+/i)||[])[0]||'';const phoneMatches=flat.match(/(?:\+?54\s?9?\s?)?(?:\(?\d{2,4}\)?[\s.-]?)?\d{3,4}[\s.-]?\d{4}/g)||[];const phone=phoneMatches.find(x=>x.replace(/\D/g,'').length>=8)||'';const loc=detectLocationV140(lines);return{file,method,text,lines,fields:{email,phone,linkedin,headline:detectHeadlineV140(lines),bio:detectBioV140(lines),city:loc.city,province:loc.province},experiences:extractExperiencesV140(lines),education:extractEducationV140(lines),skills:extractSkillsV140(text)};}

async function handleCvFileV140(file){if(!file)return;const status=document.getElementById('talentCvStatusV140');try{status.textContent='Leyendo CV localmente...';const r=await readCvV140(file,status);if((r.text||'').replace(/\s/g,'').length<80)throw new Error('No pude obtener suficiente texto del CV. Probá otra versión del archivo.');status.textContent='Analizando estructura y competencias...';const analysis=analyzeCvTextV140(r.text,file,r.method);analysis.hash=await hashFileV140(file);v140State.cv=analysis;openCvReviewV140(analysis);status.textContent=`Listo: ${analysis.experiences.length} experiencia(s), ${analysis.skills.length} competencia(s) y ${analysis.education.length} formación(es) sugeridas.`;}catch(e){console.error(e);status.textContent=e.message||'No pude leer el CV.';showToast(e.message||'No pude analizar el CV.');}}

function cvFieldRowV140(id,label,value,target,checked){return `<label class="rounded-2xl border border-slate-100 p-3 flex gap-3 items-start"><input data-v140-field="${id}" data-target="${target}" type="checkbox" ${checked?'checked':''} class="mt-1"><div class="min-w-0 flex-1"><p class="text-[10px] uppercase font-black text-slate-400">${v140Esc(label)}</p><input data-v140-value="${id}" value="${v140Esc(value||'')}" class="mt-1 w-full bg-transparent text-sm font-bold text-lutmin-dark outline-none border-b border-transparent focus:border-blue-200"></div></label>`;}
function openCvReviewV140(a){const m=ensureV100Modal('cvReviewModalV140','max-w-6xl'),b=m.querySelector('[data-v100-body]'),p=talentData?.profile||{};const f=a.fields||{};b.innerHTML=`<div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-4"><div><p class="text-[10px] uppercase tracking-widest font-black text-blue-600">Agente de CV · revisión humana</p><h2 class="mt-2 text-2xl sm:text-3xl font-black text-lutmin-dark">Confirmá lo que Lutmin encontró.</h2><p class="mt-2 text-sm text-slate-500">Archivo: ${v140Esc(a.file.name)} · método ${v140Esc(a.method)}. El archivo se procesó en este navegador; sólo se guardarán los datos que confirmes.</p></div><span class="px-3 py-1.5 rounded-full bg-emerald-50 text-emerald-700 text-[10px] font-black">API $0</span></div><div class="mt-6 grid lg:grid-cols-2 gap-5"><div><h3 class="font-extrabold text-lutmin-dark">Datos personales / profesionales</h3><div class="mt-3 grid sm:grid-cols-2 gap-2">${cvFieldRowV140('phone','Teléfono',f.phone,'phone',!p.phone&&!!f.phone)}${cvFieldRowV140('linkedin','LinkedIn',f.linkedin,'linkedin_url',!p.linkedin_url&&!!f.linkedin)}${cvFieldRowV140('city','Ciudad',f.city,'city',!p.city&&!!f.city)}${cvFieldRowV140('province','Provincia',f.province,'province',!p.province&&!!f.province)}${cvFieldRowV140('headline','Título profesional',f.headline,'headline',!p.headline&&!!f.headline)}${cvFieldRowV140('bio','Resumen profesional',f.bio,'bio',!p.bio&&!!f.bio)}</div><p class="mt-3 text-[10px] text-slate-400">El correo detectado (${v140Esc(f.email||'no encontrado')}) se usa sólo como referencia visual; Lutmin no cambia automáticamente el usuario de acceso.</p></div><div><h3 class="font-extrabold text-lutmin-dark">Competencias sugeridas</h3><div class="mt-3 flex flex-wrap gap-2">${a.skills.length?a.skills.map((s,i)=>`<label class="inline-flex items-center gap-2 px-3 py-2 rounded-xl bg-violet-50 text-violet-800 text-xs font-bold"><input data-v140-skill="${i}" type="checkbox" checked> ${v140Esc(s.skill)} <span class="opacity-50">CV</span></label>`).join(''):'<span class="text-xs text-slate-400">No encontré competencias con suficiente evidencia textual.</span>'}</div><div class="mt-4 rounded-xl bg-amber-50 p-3 text-[10px] text-amber-800"><strong>Importante:</strong> una competencia detectada en CV queda como declarada + evidencia CV. No se transforma en “validada” sin una evaluación.</div></div></div><div class="mt-6"><h3 class="font-extrabold text-lutmin-dark">Experiencia laboral detectada</h3><div class="mt-3 grid lg:grid-cols-2 gap-3">${a.experiences.length?a.experiences.map((x,i)=>`<div data-v140-exp-row="${i}" class="rounded-2xl border border-slate-100 p-4"><label class="flex items-center gap-2 text-xs font-black text-blue-700"><input data-v140-exp="${i}" type="checkbox" checked> Incorporar experiencia</label><div class="mt-3 grid gap-2"><input data-k="position" value="${v140Esc(x.position)}" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Puesto"><input data-k="company" value="${v140Esc(x.company)}" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Empresa"><div class="grid grid-cols-2 gap-2"><input data-k="start" type="date" value="${x.start||''}" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs"><input data-k="end" type="date" value="${x.end||''}" ${x.current?'disabled':''} class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs"></div><label class="text-[10px] flex items-center gap-2"><input data-k="current" type="checkbox" ${x.current?'checked':''}> Trabajo actual</label><textarea data-k="description" rows="3" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs">${v140Esc(x.description||'')}</textarea></div></div>`).join(''):'<div class="lg:col-span-2 text-xs text-slate-400">No pude estructurar experiencias automáticamente. Podés seguir usando la carga manual y las competencias detectadas.</div>'}</div></div><div class="mt-6"><h3 class="font-extrabold text-lutmin-dark">Formación detectada</h3><div class="mt-3 grid lg:grid-cols-2 gap-3">${a.education.length?a.education.map((x,i)=>`<div data-v140-edu-row="${i}" class="rounded-2xl bg-slate-50 p-4"><label class="flex items-center gap-2 text-xs font-black text-blue-700"><input data-v140-edu="${i}" type="checkbox" checked> Incorporar formación</label><input data-k="institution" value="${v140Esc(x.institution)}" class="mt-3 w-full px-3 py-2 rounded-xl bg-white border border-slate-200 text-xs"><input data-k="title" value="${v140Esc(x.title)}" class="mt-2 w-full px-3 py-2 rounded-xl bg-white border border-slate-200 text-xs"><div class="mt-2 grid grid-cols-2 gap-2"><input data-k="start" type="date" value="${x.start||''}" class="px-3 py-2 rounded-xl bg-white border border-slate-200 text-xs"><input data-k="end" type="date" value="${x.end||''}" ${x.current?'disabled':''} class="px-3 py-2 rounded-xl bg-white border border-slate-200 text-xs"></div></div>`).join(''):'<div class="lg:col-span-2 text-xs text-slate-400">No encontré una sección de formación con estructura suficiente.</div>'}</div></div><div class="mt-7 grid sm:grid-cols-3 gap-2"><button onclick="hideV100Modal('cvReviewModalV140')" class="py-3 rounded-xl bg-slate-100 text-slate-600 font-bold">Cancelar</button><button onclick="selectOnlyMissingCvFieldsV140()" class="py-3 rounded-xl bg-blue-50 text-blue-700 font-bold">Sólo completar faltantes</button><button onclick="applyCvAnalysisV140()" class="py-3 rounded-xl bg-lutmin-dark text-white font-extrabold"><i class="fa-solid fa-circle-check mr-2"></i>Aplicar lo seleccionado</button></div>`;showV100Modal('cvReviewModalV140');}
function selectOnlyMissingCvFieldsV140(){const p=talentData?.profile||{};document.querySelectorAll('[data-v140-field]').forEach(ch=>{const target=ch.dataset.target;ch.checked=!p[target]&&!!document.querySelector(`[data-v140-value="${ch.dataset.v140Field}"]`)?.value;});}
function cvRowDataV140(selector,index){const row=document.querySelector(`${selector}="${index}"]`);if(!row)return null;const v=k=>row.querySelector(`[data-k="${k}"]`)?.value?.trim()||null;return{row,v,current:!!row.querySelector('[data-k="current"]')?.checked};}
async function applyCvAnalysisV140(){const a=v140State.cv;if(!a)return;const profile={};document.querySelectorAll('[data-v140-field]:checked').forEach(ch=>{const val=document.querySelector(`[data-v140-value="${ch.dataset.v140Field}"]`)?.value?.trim();if(val)profile[ch.dataset.target]=val;});const evidence=[];const applied={fields:Object.keys(profile),experiences:0,skills:0,education:0};try{
  if(Object.keys(profile).length){profile.updated_at=new Date().toISOString();const {error}=await supabaseClient.from('talent_profiles').update(profile).eq('user_id',currentLutminUser.id);if(error)throw error;}
  const existing=talentData?.experiences||[];for(const ch of document.querySelectorAll('[data-v140-exp]:checked')){const i=Number(ch.dataset.v140Exp),r=cvRowDataV140('[data-v140-exp-row',i);if(!r)continue;const position=r.v('position'),company=r.v('company'),start=r.v('start'),end=r.current?null:r.v('end'),description=r.v('description');if(!position||!company)continue;const duplicate=existing.some(x=>v140Norm(x.position_title)===v140Norm(position)&&v140Norm(x.company_name)===v140Norm(company)&&String(x.start_date||'')===String(start||''));if(!duplicate){const {error}=await supabaseClient.from('talent_experiences').insert({user_id:currentLutminUser.id,company_name:company,position_title:position,start_date:start,end_date:end,current_job:r.current,description});if(error)throw error;applied.experiences++;}evidence.push({entity_type:'experience',entity_key:v140Norm(`${company}|${position}`),source_label:a.file.name,excerpt:`${position} · ${company}${description?' · '+description:''}`.slice(0,900),confidence:a.experiences[i]?.confidence||.7,metadata:{start_date:start,end_date:end}});}
  for(const ch of document.querySelectorAll('[data-v140-skill]:checked')){const s=a.skills[Number(ch.dataset.v140Skill)];if(!s)continue;const existingSkill=(talentData?.skills||[]).find(x=>v140Norm(x.skill)===v140Norm(s.skill));if(!existingSkill){const {error}=await supabaseClient.from('talent_skills').upsert({user_id:currentLutminUser.id,skill:s.skill,level:3,competency_id:s.competency_id||null},{onConflict:'user_id,skill'});if(error)throw error;applied.skills++;}evidence.push({entity_type:'competency',entity_key:v140Norm(s.skill),source_label:a.file.name,excerpt:s.excerpt,confidence:s.confidence,metadata:{competency_id:s.competency_id||null}});}
  for(const ch of document.querySelectorAll('[data-v140-edu]:checked')){const i=Number(ch.dataset.v140Edu),r=cvRowDataV140('[data-v140-edu-row',i);if(!r)continue;const institution=r.v('institution'),title=r.v('title');if(!institution||!title)continue;const dupe=(v140State.education||[]).some(x=>v140Norm(x.institution)===v140Norm(institution)&&v140Norm(x.title)===v140Norm(title));if(!dupe){const {error}=await supabaseClient.from('talent_education_v140').insert({user_id:currentLutminUser.id,institution,title,start_date:r.v('start'),end_date:r.v('end'),current:false,source_type:'cv'});if(error)throw error;applied.education++;}evidence.push({entity_type:'education',entity_key:v140Norm(`${institution}|${title}`),source_label:a.file.name,excerpt:`${title} · ${institution}`,confidence:a.education[i]?.confidence||.65,metadata:{}});}
  const summary={fields_detected:Object.values(a.fields||{}).filter(Boolean).length,experiences_detected:a.experiences.length,skills_detected:a.skills.length,education_detected:a.education.length,method:a.method};const {error:logError}=await supabaseClient.rpc('record_cv_import_v140',{p_file_name:a.file.name,p_file_hash:a.hash||'',p_file_type:a.file.type||a.method,p_extracted_summary:summary,p_applied_summary:applied,p_evidence:evidence});if(logError)throw logError;hideV100Modal('cvReviewModalV140');showToast(`CV incorporado: ${applied.experiences} experiencia(s), ${applied.skills} competencia(s) nueva(s) y ${applied.education} formación(es).`);await loadTalentCenter();await loadV140ProfileData();
}catch(e){console.error(e);showToast(e.message||'No pude aplicar los datos del CV.');}}

