function interviewEvidenceItemsV140(job,questions,answers){const out=[],catalog=skillCatalogV140();for(const a of answers||[]){const txt=String(a.answer||'').trim(),n=v140Norm(txt);if(txt.length<20)continue;for(const c of catalog){const hits=(c.keywords||[]).filter(k=>String(k||'').length>=4&&n.includes(v140Norm(k)));if(hits.length){const key=v140Norm(c.label);if(!out.some(x=>x.entity_key===key))out.push({entity_key:key,competency_id:c.competency_id||null,source_label:`Entrevista previa · ${job?.title||'Búsqueda'}`,excerpt:txt.slice(0,700),confidence:.62});}}}return out.slice(0,12);}
if(typeof savePreInterviewV130==='function'){
  const _savePreInterviewV140=savePreInterviewV130;
  savePreInterviewV130=async function(complete){const snap=activePreInterviewV130?{job:activePreInterviewV130.job,questions:activePreInterviewV130.questions,answers:collectPreInterviewAnswersV130()}:null;const r=await _savePreInterviewV140.apply(this,arguments);if(complete&&snap?.job?.id){try{const chk=await supabaseClient.from('job_preinterviews_v130').select('status').eq('user_id',currentLutminUser.id).eq('job_id',snap.job.id).maybeSingle();if(chk.data?.status==='completed'){const items=interviewEvidenceItemsV140(snap.job,snap.questions,snap.answers);if(items.length)await supabaseClient.rpc('record_interview_evidence_v140',{p_job_id:snap.job.id,p_items:items});}}catch(e){console.warn('Evidencia entrevista V14',e);}}return r;};
}

