async function loadProfileReviewQueueV140(){if(currentLutminUser?.role!=='admin')return;const {data,error}=await supabaseClient.rpc('admin_profile_review_queue_v140');if(error){console.warn('Queue perfil V14',error);return;}v140State.adminQueue=data||[];renderProfileReviewQueueV140();}
function renderProfileReviewQueueV140(){const root=document.getElementById('adminAgentsBodyV110');if(!root)return;root.querySelector('[data-v140-review-queue]')?.remove();const rows=v140State.adminQueue||[],box=document.createElement('div');box.dataset.v140ReviewQueue='1';box.className='mb-5 rounded-3xl border border-amber-100 overflow-hidden';box.innerHTML=`<div class="p-5 bg-amber-50 flex items-center justify-between gap-4"><div><p class="text-[10px] uppercase tracking-widest font-black text-amber-700">Perfiles · revisión humana por excepción</p><h4 class="mt-1 font-extrabold text-lutmin-dark">${rows.length?`${rows.length} perfil(es) requieren criterio humano`:'No hay perfiles esperando revisión'}</h4><p class="mt-1 text-xs text-amber-800/80">Los perfiles normales se habilitan solos. Acá llegan únicamente inconsistencias detectadas por el motor.</p></div><span class="text-3xl font-black text-amber-600">${rows.length}</span></div>${rows.length?`<div class="divide-y divide-slate-100 bg-white">${rows.map(r=>`<div class="p-4"><div class="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3"><div><p class="text-sm font-extrabold text-lutmin-dark">${v140Esc(r.full_name||r.email)}</p><p class="mt-1 text-xs text-slate-500">${v140Esc(r.headline||'Perfil profesional')} · cobertura ${Number(r.score||0)}%</p><div class="mt-2 flex flex-wrap gap-1">${(r.issues||[]).map(x=>`<span class="px-2 py-1 rounded-lg bg-amber-50 text-amber-700 text-[9px] font-bold">${v140Esc(x.label)}</span>`).join('')}</div></div><div class="flex flex-wrap gap-2"><button onclick="resolveProfileReviewV140('${r.user_id}','approve')" class="px-3 py-2 rounded-xl bg-emerald-50 text-emerald-700 text-[10px] font-bold">Aprobar excepción</button><button onclick="resolveProfileReviewV140('${r.user_id}','corrections')" class="px-3 py-2 rounded-xl bg-amber-50 text-amber-700 text-[10px] font-bold">Pedir corrección</button></div></div></div>`).join('')}</div>`:''}`;root.prepend(box);}
async function resolveProfileReviewV140(userId,action){const note=action==='corrections'?(window.prompt('Indicá brevemente qué debería corregir la persona:','Revisá la información duplicada o las fechas señaladas por Lutmin.')||''):'';if(action==='corrections'&&!note)return;const {error}=await supabaseClient.rpc('admin_resolve_profile_review_v140',{p_user_id:userId,p_action:action,p_note:note||null});if(error)return showToast(error.message||'No pude resolver la revisión.');showToast(action==='approve'?'Perfil habilitado por excepción.':'La persona verá la corrección solicitada.');await loadProfileReviewQueueV140();}
if(typeof loadAdminAgentsV110==='function'){const _loadAdminAgentsV140=loadAdminAgentsV110;loadAdminAgentsV110=async function(){const r=await _loadAdminAgentsV140.apply(this,arguments);await loadProfileReviewQueueV140();return r;};}
if(typeof refreshAllAgentsV110==='function'){const _refreshAllAgentsV140=refreshAllAgentsV110;refreshAllAgentsV110=async function(){const r=await _refreshAllAgentsV140.apply(this,arguments);await loadProfileReviewQueueV140();return r;};}

// ---------------- EMPRESA: educación + procedencia de evidencia ----------------
async function injectCompanyCandidateIntelligenceV140(userId){const root=document.getElementById('companyCandidateContent');if(!root||root.querySelector('[data-v140-company-intelligence]'))return;try{const {data,error}=await supabaseClient.rpc('company_candidate_intelligence_v140',{p_user_id:userId,p_company_id:typeof companyActiveIdV130==='function'?companyActiveIdV130():null});if(error||!data)return;const e=data.education||[],s=data.evidence_summary||{},box=document.createElement('div');box.dataset.v140CompanyIntelligence='1';box.className='mt-5 rounded-2xl border border-violet-100 bg-violet-50/40 p-4';box.innerHTML=`<p class="text-[10px] uppercase font-black text-violet-700">Evidencia estructurada Lutmin</p><div class="mt-3 grid grid-cols-4 gap-2">${[['CV',s.cv],['Entrevista',s.interview],['Curso',s.course],['Validada',s.validated]].map(x=>`<div class="rounded-xl bg-white p-3 text-center"><p class="text-[9px] uppercase font-bold text-slate-400">${x[0]}</p><p class="mt-1 text-xl font-black text-lutmin-dark">${Number(x[1]||0)}</p></div>`).join('')}</div>${e.length?`<div class="mt-4"><p class="text-xs font-extrabold text-lutmin-dark">Formación externa</p><div class="mt-2 space-y-2">${e.map(x=>`<div class="rounded-xl bg-white p-3"><p class="text-xs font-bold text-lutmin-dark">${v140Esc(x.title)}</p><p class="text-[10px] text-slate-500">${v140Esc(x.institution)}${x.level?' · '+v140Esc(x.level):''}</p></div>`).join('')}</div></div>`:''}<p class="mt-3 text-[10px] text-slate-500">La procedencia ayuda a interpretar el perfil. CV y entrevista son evidencia declarada; no equivalen a una competencia validada.</p>`;root.firstElementChild?.insertAdjacentElement('afterend',box);}catch(e){console.warn('Company intelligence V14',e);}}
if(typeof openCompanyCandidateProfile==='function'){const _openCompanyCandidateProfileV140=openCompanyCandidateProfile;openCompanyCandidateProfile=async function(userId,applicationId=null){const r=await _openCompanyCandidateProfileV140.apply(this,arguments);await injectCompanyCandidateIntelligenceV140(userId);return r;};}

