if(typeof buildCvSnapshotV100==='function'){const _buildCvSnapshotV140=buildCvSnapshotV100;buildCvSnapshotV100=function(a){const s=_buildCvSnapshotV140.apply(this,arguments);s.version='LUTMIN-CV-DYNAMIC-V14';s.education=(v140State.education||[]).map(x=>({institution:x.institution,title:x.title,level:x.level,start_date:x.start_date,end_date:x.end_date,current:x.current}));return s;};}

async function downloadTalentCvPdf(){if(!(await ensureJsPdfLib()))return showToast('No se pudo cargar el generador PDF.');if(!talentData.profile)return showToast('Primero completá tu perfil.');const {jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4'}),p=talentData.profile;let y=20;const page=()=>{if(y>270){doc.addPage();y=20;}};doc.setFont('helvetica','bold');doc.setFontSize(22);doc.text(currentLutminUser.fullName||'Perfil profesional',18,y);y+=8;doc.setFontSize(12);doc.setTextColor(47,141,253);doc.text(p.headline||'Perfil profesional Lutmin',18,y);y+=10;doc.setFont('helvetica','normal');doc.setFontSize(9);doc.setTextColor(80);doc.text([p.city,p.province].filter(Boolean).join(', ')||'Ubicación no informada',18,y);y+=5;doc.text(`${talentAvailabilityLabel(p.availability)}${p.willing_travel?' · Disponible para viajar':''}`,18,y);y+=9;if(p.bio){doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Sobre mí',18,y);y+=6;doc.setFont('helvetica','normal');doc.setTextColor(70);const l=doc.splitTextToSize(p.bio,174);doc.text(l,18,y);y+=l.length*4+6;}doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Competencias',18,y);y+=6;doc.setFont('helvetica','normal');doc.setTextColor(70);const sl=doc.splitTextToSize(talentData.skills.map(x=>talentSkillTextV33(x)).join(' · ')||'Sin competencias cargadas',174);doc.text(sl,18,y);y+=sl.length*4+7;for(const x of talentData.experiences||[]){page();if(x===talentData.experiences[0]){doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Experiencia',18,y);y+=6;}doc.setFont('helvetica','bold');doc.setTextColor(40);doc.text(`${x.position_title} · ${x.company_name}`,18,y);y+=5;doc.setFont('helvetica','normal');doc.setTextColor(100);doc.text(`${x.start_date||''} - ${x.current_job?'Actualidad':x.end_date||''}`,18,y);y+=4;if(x.description){const l=doc.splitTextToSize(x.description,170);doc.text(l,18,y);y+=l.length*4+4;}}if((v140State.education||[]).length){page();y+=3;doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Formación',18,y);y+=6;for(const x of v140State.education){page();doc.setFont('helvetica','bold');doc.setTextColor(50);doc.text(`${x.title} · ${x.institution}`,18,y);y+=4.5;doc.setFont('helvetica','normal');doc.setTextColor(100);doc.text(`${x.start_date||''} - ${x.current?'Actualidad':x.end_date||''}${x.level?' · '+x.level:''}`,18,y);y+=5;}}if(talentData.certificates?.length){page();doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Certificaciones Lutmin',18,y);y+=6;doc.setFont('helvetica','normal');doc.setTextColor(70);for(const c of talentData.certificates){page();doc.text(`• ${c.course_title} · ${c.duration_hours} h · ${Math.round(Number(c.score||0))}% · ${c.code}`,18,y);y+=5;}}doc.setFontSize(7);doc.setTextColor(140);doc.text('CV generado desde Lutmin Conecta. Las competencias validadas se distinguen de las declaradas y detectadas por CV.',18,290);doc.save(`CV_${slugifyLutmin(currentLutminUser.fullName||'Lutmin')}.pdf`);}

async function downloadSmartCvV100(jobId=null){const job=(talentData?.jobs||[]).find(x=>x.id===(jobId||agentJobV100?.id));if(!job)return showToast('Elegí una búsqueda para generar el CV.');if(!(await ensureJsPdfLib()))return showToast('No se pudo iniciar el generador PDF.');const a=buildAgentAnalysisV100(job),snap=buildCvSnapshotV100(a),{jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4'});let y=18;const page=()=>{if(y>270){doc.addPage();y=18;}};doc.setFont('helvetica','bold');doc.setFontSize(21);doc.setTextColor(10,24,79);doc.text(currentLutminUser?.fullName||'Perfil profesional',18,y);y+=7;doc.setFontSize(11);doc.setTextColor(47,141,253);doc.text(snap.profile.headline,18,y);y+=7;doc.setFontSize(8);doc.setFont('helvetica','normal');doc.setTextColor(90);doc.text(`CV adaptado para: ${job.title}${job.company_name?' · '+job.company_name:''}`,18,y);y+=5;doc.text([snap.profile.city,snap.profile.province].filter(Boolean).join(', ')||'Ubicación no informada',18,y);y+=8;if(snap.focus_terms.length){doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Enfoque de esta postulación',18,y);y+=5;doc.setFont('helvetica','normal');doc.setTextColor(70);const l=doc.splitTextToSize(`Evidencia del perfil relacionada con la búsqueda: ${snap.focus_terms.join(' · ')}.`,174);doc.text(l,18,y);y+=l.length*4+6;}if(snap.profile.bio){doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Perfil',18,y);y+=5;doc.setFont('helvetica','normal');doc.setTextColor(70);const l=doc.splitTextToSize(snap.profile.bio,174);doc.text(l,18,y);y+=l.length*4+6;}doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Competencias priorizadas',18,y);y+=6;doc.setFont('helvetica','normal');doc.setTextColor(70);const sl=doc.splitTextToSize(snap.skills.slice(0,10).map(s=>`${s.skill} (${s.level}/5)`).join(' · ')||'Sin competencias cargadas',174);doc.text(sl,18,y);y+=sl.length*4+7;if(snap.experiences.length){doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Experiencia',18,y);y+=6;for(const x of snap.experiences){page();doc.setFont('helvetica','bold');doc.setTextColor(50);doc.text(`${x.position_title} · ${x.company_name}`,18,y);y+=4.5;doc.setFont('helvetica','normal');doc.setTextColor(100);doc.text(`${x.start_date||''} - ${x.current_job?'Actualidad':x.end_date||''}`,18,y);y+=4;if(x.description){const l=doc.splitTextToSize(x.description,170);doc.text(l,18,y);y+=l.length*3.8+4;}}}if((snap.education||[]).length){page();doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Formación relevante',18,y);y+=6;for(const x of snap.education){page();doc.setFont('helvetica','bold');doc.setTextColor(50);doc.text(`${x.title} · ${x.institution}`,18,y);y+=4.5;doc.setFont('helvetica','normal');doc.setTextColor(100);doc.text(`${x.start_date||''} - ${x.current?'Actualidad':x.end_date||''}${x.level?' · '+x.level:''}`,18,y);y+=5;}}if(snap.certificates.length){page();doc.setFont('helvetica','bold');doc.setTextColor(10,24,79);doc.text('Certificaciones Lutmin',18,y);y+=6;doc.setFont('helvetica','normal');doc.setTextColor(70);for(const c of snap.certificates.slice(0,10)){page();doc.text(`• ${c.course_title}${c.duration_hours?' · '+c.duration_hours+' h':''}${c.code?' · '+c.code:''}`,18,y);y+=4.5;}}doc.setFontSize(6.5);doc.setTextColor(140);doc.text('Generado por el motor local de Lutmin. Reordena únicamente datos reales confirmados; no inventa antecedentes ni garantiza resultados de selección.',18,290);doc.save(`CV_${slugifyLutmin(currentLutminUser?.fullName||'Lutmin')}_${slugifyLutmin(job.title)}.pdf`);}

